"""Four named source-camera actor construction at the pinned CPU profile.

Callers supply source-grounded static transforms for overview/approach/corner
and a relative driver transform. Real pixel coverage must be audited after run.
"""

from contextlib import contextmanager


SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
         "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


@contextmanager
def source_cameras(world, ego, transforms):
    if set(transforms) != set(SIZES):
        raise ValueError("All four named source-camera transforms required")
    sensors = {}
    try:
        for name, (width, height) in SIZES.items():
            blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
            blueprint.set_attribute("image_size_x", str(width))
            blueprint.set_attribute("image_size_y", str(height))
            blueprint.set_attribute("fov", "90")
            blueprint.set_attribute("sensor_tick", "0.05")
            kwargs = {"attach_to": ego} if name == "driver_reference" else {}
            sensor = world.spawn_actor(blueprint, transforms[name], **kwargs)
            if sensor is None:
                raise ValueError("Native camera spawn failed: " + name)
            sensors[name] = sensor
        yield sensors
    finally:
        for sensor in reversed(list(sensors.values())):
            sensor.stop()
            sensor.destroy()

"""Portable speed staging for C158190's selected yield-sign comparison.

Distances and crossing state must be read from the eventual Native runner.
These speeds are construction targets, not legal hazard or yielding cutoffs.
"""
from dataclasses import dataclass
import math

PREFIX = 'testing__C158190__NRS-484B-257-1__motor_vehicle_driver__'


@dataclass(frozen=True)
class Stage:
    case_id: str
    approach_speed_mps: float = 6.0
    view_speed_mps: float = 2.0
    clear_speed_mps: float = 4.0
    view_bracket_m: float = 15.0

    def __post_init__(self):
        allowed = ('yield_nearest_view_sign_angle_zero',
                   'yield_nearest_view_through_entered',
                   'yield_nearest_view_clear',
                   'yield_nearest_view_no_slow')
        if self.case_id not in {PREFIX + suffix for suffix in allowed}:
            raise ValueError('Unknown exact C158190 case')
        if any(not math.isfinite(value) or value <= 0 for value in
               (self.approach_speed_mps, self.view_speed_mps,
                self.clear_speed_mps, self.view_bracket_m)):
            raise ValueError('Invalid staging parameters')
        if self.view_speed_mps >= self.approach_speed_mps:
            raise ValueError('View-stage construction must slow the ego')

    def target(self, distance_to_intersection_m, *, within_intersection,
               through_vehicle_clear):
        if (not isinstance(distance_to_intersection_m, (int, float))
                or not math.isfinite(distance_to_intersection_m)
                or distance_to_intersection_m < 0):
            raise ValueError('Missing Native approach distance')
        if type(within_intersection) is not bool or type(through_vehicle_clear) is not bool:
            raise ValueError('Missing Native crossing state')
        if self.case_id.endswith('__yield_nearest_view_no_slow'):
            return self.approach_speed_mps
        if within_intersection:
            return self.clear_speed_mps
        if distance_to_intersection_m <= self.view_bracket_m:
            return self.clear_speed_mps if through_vehicle_clear else self.view_speed_mps
        return self.approach_speed_mps


def speed_control(target_mps, observed_mps, *, gain=.25):
    """Simple bounded longitudinal command for a CARLA adapter to apply."""
    if any(not isinstance(x, (int, float)) or not math.isfinite(x) or x < 0
           for x in (target_mps, observed_mps)):
        raise ValueError('Missing observed or target speed')
    delta = (target_mps - observed_mps) * gain
    return {'throttle': min(1.0, max(0.0, delta)),
            'brake': min(1.0, max(0.0, -delta))}

"""Retain Native control and crossing inventories without legal conclusions."""

import json
import math
from pathlib import Path


def _xyz(point):
    return [float(point.x), float(point.y), float(point.z)]


def observe_controls(world, expected_yield_id, *, frame=None):
    """Sample current actors/map once; a sign face still needs pixel review."""
    if frame is not None and world.get_snapshot().frame != frame:
        raise ValueError('Control inventory frame differs from current world')
    actors = list(world.get_actors())
    yield_signs = [actor for actor in actors if actor.type_id.startswith('traffic.yield')]
    matched = [actor for actor in yield_signs if actor.id == expected_yield_id]
    if len(matched) != 1:
        raise ValueError('Native yield sign disappeared or changed identity')
    sign = matched[0]
    transform = sign.get_transform()
    if not all(math.isfinite(float(getattr(transform.rotation, axis)))
               for axis in ('yaw', 'pitch', 'roll')):
        raise ValueError('Native yield sign rotation is not finite')
    if not hasattr(sign, 'trigger_volume'):
        raise ValueError('Native yield sign lacks trigger volume')
    trigger = [_xyz(point) for point in
               sign.trigger_volume.get_world_vertices(transform)]
    if len(trigger) < 4:
        raise ValueError('Native yield trigger geometry incomplete')
    crosswalks = [_xyz(point) for point in world.get_map().get_crosswalks()]
    competing = [{'actor_id': actor.id, 'blueprint': actor.type_id,
                  'position_m': _xyz(actor.get_transform().location)}
                 for actor in actors if actor.type_id.startswith(
                     ('traffic.stop', 'traffic.traffic_light'))]
    return {'frame': frame, 'native_map_name': world.get_map().name,
            'yield_sign': {'actor_id': sign.id, 'blueprint': sign.type_id,
                           'position_m': _xyz(transform.location),
                           'native_rotation_deg': {
                               'yaw': float(transform.rotation.yaw),
                               'pitch': float(transform.rotation.pitch),
                               'roll': float(transform.rotation.roll)},
                           'trigger_vertices_m': trigger},
            'other_yield_sign_ids': [actor.id for actor in yield_signs if actor.id != sign.id],
            'competing_controls': competing,
            'native_crosswalk_vertices_m': crosswalks,
            'stop_line_decal_absence': 'unverified_from_Native_control_inventory',
            'sign_face_legibility': 'unverified_from_Native_control_inventory',
            'police_direction': 'unverified_from_Native_control_inventory'}


class ControlWriter:
    def __init__(self, root):
        self.path = Path(root) / 'control_inventory.jsonl'
        if self.path.exists():
            raise ValueError('Retain prior Native control inventory')
        self.previous_frame = -1

    def add(self, row):
        frame = row.get('frame')
        if type(frame) is not int or frame <= self.previous_frame:
            raise ValueError('Control inventory frames must increase')
        with self.path.open('a') as stream:
            stream.write(json.dumps(row, sort_keys=True) + '\n')
        self.previous_frame = frame

"""Retain original participant bodies for saved intersection completion checks."""

import json
import math
from pathlib import Path

INTERSECTION_POLYGON = [[-8.0, -8.0], [8.0, -8.0], [8.0, 8.0], [-8.0, 8.0]]


def _xyz(point):
    values = [float(point.x), float(point.y), float(point.z)]
    if not all(math.isfinite(v) for v in values):
        raise ValueError('Nonfinite original body point')
    return values


def _body(world, actor):
    transform = actor.get_transform()
    vertices = [_xyz(point) for point in actor.bounding_box.get_world_vertices(transform)]
    if len(vertices) < 4:
        raise ValueError('Incomplete original actor body')
    waypoint = world.get_map().get_waypoint(transform.location, project_to_road=False)
    if waypoint is None:
        raise ValueError('Original actor has no Native road waypoint')
    return {'actor_id': actor.id, 'blueprint': actor.type_id,
            'position_m': _xyz(transform.location),
            'road_id': waypoint.road_id, 'lane_id': waypoint.lane_id,
            'body_vertices_m': vertices}


def observe_interaction(world, ego, through, frame, time_s):
    if world.get_snapshot().frame != frame or type(frame) is not int:
        raise ValueError('Interaction observation frame differs')
    if isinstance(time_s, bool) or not isinstance(time_s, (int, float)) or not math.isfinite(time_s):
        raise ValueError('Missing original interaction time')
    ego_state = _body(world, ego)
    through_state = None if through is None else _body(world, through)
    if world.get_snapshot().frame != frame:
        raise ValueError('World advanced during interaction observation')
    return {'frame': frame, 'time_s': float(time_s),
            'ego': ego_state, 'through': through_state}


class InteractionWriter:
    def __init__(self, root):
        self.root = Path(root)
        self.path = self.root / 'interaction_history.jsonl'
        self.context = self.root / 'control_context.json'
        if self.path.exists() or self.context.exists():
            raise ValueError('Retain prior interaction sources')
        self.context.write_text(json.dumps({
            'intersection_xy_m': INTERSECTION_POLYGON,
            'source': 'authored OpenDRIVE junction bounds; Native map facts and body overlap required',
            'engineering_extent_not_legal_line': True}, indent=2) + '\n')
        self.previous = (-1, -math.inf)

    def add(self, row):
        frame, time_s = row.get('frame'), row.get('time_s')
        if (type(frame) is not int or frame <= self.previous[0]
                or isinstance(time_s, bool) or not isinstance(time_s, (int, float))
                or not math.isfinite(time_s) or time_s <= self.previous[1]):
            raise ValueError('Nonmonotone original interaction frame')
        with self.path.open('a') as stream:
            stream.write(json.dumps(row, sort_keys=True, allow_nan=False) + '\n')
        self.previous = (frame, time_s)

"""Source-bound observations for the nearest-view yield-sign branch.

Visibility samples and sign/marking provenance must come from retained Native
and source-camera evidence. This reports speed and sight points, not whether an
approaching vehicle posed an immediate hazard or whether yielding was adequate.
"""

import hashlib
import json
import math
from pathlib import Path


REQUIRED = ("approach_history.jsonl", "visibility_samples.json", "visibility_rays.jsonl",
            "road_context.json", "video_frames.jsonl")


def _finite(value, label):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError("Missing finite " + label)
    return float(value)


def _rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def analyze(root: Path, *, reviewed_context=None) -> dict:
    root = Path(root)
    sources = {}
    for name in REQUIRED:
        path = root / name
        if not path.is_file():
            raise ValueError("Missing source: " + name)
        sources[name] = hashlib.sha256(path.read_bytes()).hexdigest()
    context = (json.loads((root / "road_context.json").read_text())
               if reviewed_context is None else reviewed_context)
    for key in ("native_map_id", "intersection_id", "approach_road_id",
                "approach_lane_id", "through_highway_id", "native_yield_sign_id",
                "sign_governance_source", "marking_inventory_source"):
        if context.get(key) is None:
            raise ValueError("Missing sourced road/sign context: " + key)
    if context.get("no_stop_line") is not True or context.get("no_near_crosswalk") is not True:
        raise ValueError("Nearest-view branch needs sourced absence of stop line and crosswalk")
    if context.get("police_control") is not False or context.get("traffic_signal_control") is not False:
        raise ValueError("Control exception not excluded by source context")
    samples = json.loads((root / "visibility_samples.json").read_text())
    if not isinstance(samples, list) or len(samples) < 2:
        raise ValueError("Insufficient approach visibility samples")
    rays = _rows(root / "visibility_rays.jsonl")
    ray_by_frame = {row.get("frame"): row for row in rays}
    if len(ray_by_frame) != len(rays) or len(rays) != len(samples):
        raise ValueError("Sight rays do not cover each approach sample once")
    visible = []
    for sample in samples:
        distance = _finite(sample.get("distance_to_intersection_m"), "sight-sample distance")
        if distance < 0 or sample.get("ray_source") != "visibility_rays.jsonl":
            raise ValueError("Visibility sample lacks spatial ray evidence")
        frame = sample.get("frame")
        ray = ray_by_frame.get(frame)
        if (type(frame) is not int or ray is None
                or ray.get("distance_to_intersection_m") != distance
                or not isinstance(ray.get("observer_m"), list)
                or not isinstance(ray.get("target_m"), list)
                or not isinstance(ray.get("blockers"), list)
                or type(ray.get("clear")) is not bool
                or ray["clear"] != (not ray["blockers"])):
            raise ValueError("Visibility sample does not join a complete original ray")
        road_visible = sample.get("through_highway_visible")
        if type(road_visible) is not bool or road_visible != ray["clear"]:
            raise ValueError("Through-highway view differs from original ray")
        ids = sample.get("visible_through_vehicle_ids")
        if not isinstance(ids, list) or ids != ray.get("visible_through_vehicle_ids"):
            raise ValueError("Missing through-traffic visibility result")
        if ids and not road_visible:
            raise ValueError("Visible through vehicle without a through-highway sight path")
        if road_visible:
            visible.append({"frame": frame, "distance_to_intersection_m": distance,
                            "visible_through_vehicle_ids": ids,
                            "ray_source": sample["ray_source"]})
    if not visible:
        raise ValueError("No sourced view of the through highway")
    closest = min(visible, key=lambda sample: sample["distance_to_intersection_m"])
    history, frames = _rows(root / "approach_history.jsonl"), _rows(root / "video_frames.jsonl")
    if len(history) < 2 or len(history) > len(frames):
        raise ValueError("Incomplete approach/frame history")
    if {row.get("frame") for row in history} != set(ray_by_frame):
        raise ValueError("Sight rays do not join original approach frames")
    frame_by_id = {row.get("carla_frame"): row for row in frames}
    if len(frame_by_id) != len(frames):
        raise ValueError("Duplicate original camera frame")
    frame_previous = (-1, -math.inf)
    for index, frame in enumerate(frames):
        fid, time = frame.get('carla_frame'), _finite(frame.get('time_s'), 'camera time')
        if (type(fid) is not int or fid <= frame_previous[0] or time <= frame_previous[1]
                or frame.get('video_frame') != index):
            raise ValueError('Nonmonotone original camera frame map')
        frame_previous = (fid, time)
    previous = (-1, -math.inf)
    speed_samples = []
    for row in history:
        fid, time = row.get("frame"), _finite(row.get("time_s"), "time")
        if type(fid) is not int or fid <= previous[0] or time <= previous[1]:
            raise ValueError("Nonmonotone original history")
        previous = (fid, time)
        frame = frame_by_id.get(fid)
        if frame is None or frame.get("time_s") != time:
            raise ValueError("Original frame join failed")
        if row.get("road_id") != context["approach_road_id"] or row.get("lane_id") != context["approach_lane_id"]:
            raise ValueError("Ego outside sign-governed approach")
        speed = _finite(row.get("ego_speed_mps"), "ego speed")
        distance = _finite(row.get("distance_to_intersection_m"), "ego distance")
        if speed < 0 or distance < 0:
            raise ValueError("Invalid ego approach sample")
        if distance != ray_by_frame[fid]['distance_to_intersection_m']:
            raise ValueError('Sight ray and original ego distance differ')
        speed_samples.append({"frame": fid, "time_s": time,
                              "ego_speed_mps": speed,
                              "distance_to_intersection_m": distance})
    return {"format": "worker-nearest-view-yield-observations", "sources": sources,
            "intersection_id": context["intersection_id"], "native_yield_sign_id": context["native_yield_sign_id"],
            "closest_sourced_visible_sample": closest,
            "speed_at_closest_view_mps": next(row['ego_speed_mps'] for row in speed_samples
                                              if row['frame'] == closest['frame']),
            "minimum_observed_approach_speed_mps": min(row["ego_speed_mps"] for row in speed_samples),
            "approach_speed_samples": speed_samples,
            "immediate_hazard_judgment": "unresolved; no legal time-to-conflict cutoff",
            "yield_judgment": "unresolved"}

import sys
import unittest
from pathlib import Path
from types import SimpleNamespace as NS

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from yield_construction import stage_case

PREFIX = 'testing__C158190__NRS-484B-257-1__motor_vehicle_driver__'


class Map:
    name = 'OpenDriveMap'
    lanes = {(-20, 1.8): (158190, -1, False),
             (0, 1.8): (158192, -1, True),
             (1.8, 20): (158194, -1, False),
             (1.8, 0): (158195, -1, True),
             (-1.8, -20): (158196, 1, False),
             (-60, 1.8): (158190, -1, False),
             (1.8, 45): (158194, -1, False),
             (1.8, 4): (158195, -1, True)}

    def get_waypoint(self, point, project_to_road=False):
        assert project_to_road is False
        road, lane, junction = self.lanes[(point.x, point.y)]
        return NS(road_id=road, lane_id=lane, is_junction=junction,
                  transform=NS(location=point))


class Actors:
    def filter(self, name):
        assert name == 'traffic.yield*'
        return [NS(id=500, trigger_volume=NS(contains=lambda point, transform:
                                            (point.x, point.y) == (-20, 1.8)),
                   get_transform=lambda: object())]


class World:
    def __init__(self, fail_second=False):
        self.map = Map()
        self.spawned = []
        self.fail_second = fail_second

    def get_map(self):
        return self.map

    def get_actors(self):
        return Actors()

    def get_blueprint_library(self):
        return NS(find=lambda name: name)

    def try_spawn_actor(self, blueprint, transform):
        if self.fail_second and self.spawned:
            return None
        actor = NS(id=len(self.spawned) + 1, type_id=blueprint,
                   get_location=lambda: transform.location,
                   destroy=lambda: None)
        actor.destroy = lambda: setattr(actor, 'destroyed', True)
        actor.destroyed = False
        self.spawned.append(actor)
        return actor


class ConstructionTests(unittest.TestCase):
    @staticmethod
    def location(**values):
        return NS(**values)

    def test_approaching_entered_and_clear_roles_cleanup(self):
        for suffix, expected_road, expected_point in (
                ('yield_nearest_view_sign_angle_zero', 158194, (1.8, 45)),
                ('yield_nearest_view_through_entered', 158195, (1.8, 4)),
                ('yield_nearest_view_clear', None, None)):
            with self.subTest(suffix=suffix):
                world = World()
                with stage_case(world, PREFIX + suffix, location_factory=self.location) as staged:
                    self.assertEqual(staged['ego'].id, 1)
                    self.assertEqual(staged['through_spawn_point_xy_m'], expected_point)
                    self.assertEqual(len(world.spawned), 1 if expected_road is None else 2)
                    if expected_road is not None:
                        self.assertEqual(world.map.get_waypoint(staged['through'].get_location()).road_id,
                                         expected_road)
                self.assertTrue(all(actor.destroyed for actor in world.spawned))

    def test_failure_destroys_owned_ego(self):
        world = World(fail_second=True)
        with self.assertRaisesRegex(ValueError, 'could not spawn'):
            with stage_case(world, PREFIX + 'yield_nearest_view_no_slow',
                            location_factory=self.location):
                pass
        self.assertEqual(len(world.spawned), 1)
        self.assertTrue(world.spawned[0].destroyed)


if __name__ == '__main__':
    unittest.main()

import json
import sys
import tempfile
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from yield_interaction_sources import InteractionWriter, observe_interaction


class Point:
    def __init__(self, x=0, y=0, z=0):
        self.x, self.y, self.z = x, y, z


class Actor:
    def __init__(self, ident):
        self.id = ident
        self.type_id = 'vehicle.tesla.model3'
        self.bounding_box = type('Box', (), {'get_world_vertices': lambda self, transform:
                            [Point(i, 0, 0) for i in range(8)]})()

    def get_transform(self):
        return type('Transform', (), {'location': Point(0,0,0)})()


class World:
    frame = 100

    def get_snapshot(self):
        return type('Snapshot', (), {'frame': self.frame})()

    def get_map(self):
        return type('Map', (), {'get_waypoint': lambda self, location, project_to_road=False:
                    type('Waypoint', (), {'road_id': 158195, 'lane_id': -1})()})()


class InteractionTests(unittest.TestCase):
    def test_retains_bodies_and_context_for_physical_check(self):
        world = World()
        row = observe_interaction(world, Actor(1), Actor(2), 100, 5.)
        self.assertEqual(len(row['ego']['body_vertices_m']), 8)
        self.assertEqual(row['through']['actor_id'], 2)
        self.assertEqual(row['through']['road_id'], 158195)
        with tempfile.TemporaryDirectory() as directory:
            writer = InteractionWriter(directory)
            writer.add(row)
            self.assertEqual(json.loads(Path(directory, 'interaction_history.jsonl').read_text())['frame'], 100)
            self.assertEqual(len(json.loads(Path(directory, 'control_context.json').read_text())['intersection_xy_m']), 4)
            with self.assertRaisesRegex(ValueError, 'Nonmonotone'):
                writer.add(row)

    def test_rejects_stale_world_frame(self):
        with self.assertRaisesRegex(ValueError, 'frame differs'):
            observe_interaction(World(), Actor(1), None, 99, 5.)
